package com.rekluzlabs.makokolorize.data.imageimport android.content.Contextimport android.graphics.Bitmapimport android.graphics.BitmapFactoryimport android.graphics.Matriximport android.net.Uriimport android.provider.MediaStoreimport androidx.exifinterface.media.ExifInterfaceimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport java.io.Fileimport java.io.FileOutputStreamimport java.util.concurrent.atomic.AtomicIntegerclass ImageRepository(private val context: Context) {    private val sessionCounter = AtomicInteger(0)    suspend fun saveProcessedBitmap(bitmap: Bitmap): Result<Uri> = withContext(Dispatchers.IO) {        try {            val sessionId = sessionCounter.incrementAndGet().toString()            val dir = File(context.cacheDir, "restore/session_$sessionId")            dir.mkdirs()            val file = File(dir, "result.png")            FileOutputStream(file).use { out ->                bitmap.compress(Bitmap.CompressFormat.PNG, 100, out)            }            Result.success(Uri.fromFile(file))        } catch (e: Exception) {            Result.failure(e)        }    }    fun cleanupCache() {        val dir = File(context.cacheDir, "restore")        if (dir.exists()) {            dir.deleteRecursively()        }    }    suspend fun loadBitmap(uri: Uri, maxDimension: Int = 2048): Result<Bitmap> = withContext(Dispatchers.IO) {        try {            val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }                ?: return@withContext Result.failure(Exception("Failed to read image"))            val options = BitmapFactory.Options().apply {                inJustDecodeBounds = true            }            BitmapFactory.decodeByteArray(bytes, 0, bytes.size, options)            if (options.outWidth <= 0 || options.outHeight <= 0) {                return@withContext Result.failure(Exception("Failed to decode image bounds"))            }            val sampleSize = calculateSampleSize(options.outWidth, options.outHeight, maxDimension)            val finalOptions = BitmapFactory.Options().apply {                inSampleSize = sampleSize            }            val bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size, finalOptions)                ?: return@withContext Result.failure(Exception("Failed to decode image"))            val corrected = correctOrientation(uri, bitmap)            Result.success(corrected)        } catch (e: Exception) {            Result.failure(e)        }    }    suspend fun fetchLocalImages(): Result<List<Uri>> = withContext(Dispatchers.IO) {        try {            val uris = mutableListOf<Uri>()            val projection = arrayOf(MediaStore.Images.Media._ID)            val sortOrder = "${MediaStore.Images.Media.DATE_ADDED} DESC"            context.contentResolver.query(                MediaStore.Images.Media.EXTERNAL_CONTENT_URI,                projection, null, null, sortOrder            )?.use { cursor ->                val idColumn = cursor.getColumnIndexOrThrow(MediaStore.Images.Media._ID)                while (cursor.moveToNext()) {                    val id = cursor.getLong(idColumn)                    uris.add(Uri.withAppendedPath(MediaStore.Images.Media.EXTERNAL_CONTENT_URI, id.toString()))                }            }            Result.success(uris)        } catch (e: Exception) {            Result.failure(e)        }    }    private fun calculateSampleSize(width: Int, height: Int, maxDimension: Int): Int {        if (width <= maxDimension && height <= maxDimension) return 1        val longestSide = maxOf(width, height)        var sampleSize = 1        while (longestSide / sampleSize > maxDimension) {            sampleSize *= 2        }        return sampleSize    }    private fun correctOrientation(uri: Uri, bitmap: Bitmap): Bitmap {        try {            context.contentResolver.openInputStream(uri)?.use { input ->                val exif = ExifInterface(input)                val rotation = when (exif.getAttributeInt(                    ExifInterface.TAG_ORIENTATION,                    ExifInterface.ORIENTATION_NORMAL                )) {                    ExifInterface.ORIENTATION_ROTATE_90 -> 90f                    ExifInterface.ORIENTATION_ROTATE_180 -> 180f                    ExifInterface.ORIENTATION_ROTATE_270 -> 270f                    else -> 0f                }                if (rotation != 0f) {                    val matrix = Matrix().apply { postRotate(rotation) }                    val rotated = Bitmap.createBitmap(                        bitmap, 0, 0, bitmap.width, bitmap.height, matrix, true                    )                    if (rotated != bitmap) bitmap.recycle()                    return rotated                }            }        } catch (_: Exception) { }        return bitmap    }    suspend fun saveBitmap(bitmap: Bitmap, format: Bitmap.CompressFormat, quality: Int = 95): Result<Uri> = withContext(Dispatchers.IO) {        try {            val dir = File(context.filesDir, "exports")            dir.mkdirs()            val ext = if (format == Bitmap.CompressFormat.JPEG) "jpg" else "png"            val file = File(dir, "makokolorize_${System.currentTimeMillis()}.$ext")            FileOutputStream(file).use { out ->                bitmap.compress(format, quality, out)            }            Result.success(Uri.fromFile(file))        } catch (e: Exception) {            Result.failure(e)        }    }}